    if worst_score >= 100:
        return "invalid"
    if worst_score >= 25:
        return "severe"
    if worst_score >= 10:
        return "moderate"
    if worst_score >= 3:
        return "minor"
    return "clean"


def _label_counts(labels: list) -> dict:
    counts = {"clean": 0, "minor": 0, "moderate": 0, "severe": 0, "invalid": 0}
    for label in labels:
        counts[label] = counts[label] + 1
    return counts


def _trend(values: list) -> str:
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list) -> int:
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current = current + 1
            if current > longest:
                longest = current
    return longest


def _verdict(total: int) -> str:
    if total >= 100:
        return "fail"
    if total >= 25:
        return "warn"
    return "pass"


def _summary_line(count: int, gaps: int, worst_score: int, total: int) -> str:
    return "n=" + str(count) + ";gaps=" + str(gaps) + ";worst=" + _worst_label(worst_score) + ";score=" + str(total)

