def _bands(hard_limit: int) -> tuple:
    # Each row is (threshold, label, score); first row whose threshold a
    # deviation reaches wins, so the same dispatch drives label, score,
    # worse-case labelling, and totals.
    return (
        (hard_limit, "invalid", 100),
        (12, "severe", 25),
        (6, "moderate", 10),
        (3, "minor", 3),
        (0, "clean", 0),
    )


def classify_spikes(deviations: list, hard_limit: int) -> tuple:
    bands = _bands(hard_limit)
    labels = []
    total = 0
    worst = 0
    for deviation in deviations:
        for threshold, label, score in bands:
            if deviation >= threshold:
                labels.append(label)
                total = total + score
                if score > worst:
                    worst = score
                break
    return labels, total, worst


def _worst_label(worst_score: int) -> str:
    for _threshold, label, score in _bands(0):
        if worst_score >= score:
            return label
    return "clean"

