def ref_classify(devs,hl):
    labels=[];total=0;worst=0
    for d in devs:
        if d>=hl: label="invalid"; score=100
        elif d>=12: label="severe"; score=25
        elif d>=6: label="moderate"; score=10
        elif d>=3: label="minor"; score=3
        else: label="clean"; score=0
        labels.append(label);total+=score
        if score>worst: worst=score
    return labels,total,worst
